"""Explain wake-one IRQ restoration, wake-all batches, completion and prepare."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1497': ('알림 벨을 잠깐 꺼 두고 대기 명단에서 한 사람을 부른 뒤, 벨을 원래 상태로 돌린다고 생각해 봅시다. 원래 꺼져 있었다면 끝날 때도 꺼져 있어야 합니다.', '한 항목 깨우기와 인터럽트의 이전 상태 복원을 이해합니다.', '시작 상태를 켜짐과 꺼짐으로 나누어 쓰세요. 두 경우 모두 작업 중 꺼짐을 거쳐 끝에는 원래 상태로 돌아가는 화살표를 그리세요.', ['swake_up_one은 대기 줄에서 첫 항목 하나를 처리하는 함수입니다. 줄이 비어 있다면 처리할 작업이 없습니다. one이라는 이름은 빈 줄에서도 반드시 한 작업이 새로 깨어난다는 보장이 아닙니다.', '먼저 raw_spin_lock_irqsave로 줄의 잠금을 잡습니다. IRQ는 인터럽트, 즉 CPU가 처리할 사건 알림을 가리킵니다. irqsave는 해당 CPU의 이전 인터럽트 상태를 flags에 저장하고 인터럽트를 끄며 잠금을 잡는 방식입니다.', '이때 flags는 이전 상태를 기억하는 지역 변수입니다. 앞 수업의 대기 항목에 붙이는 EXCLUSIVE 같은 표시와 같은 칸이 아닙니다. 같은 변수 이름도 어떤 자료를 저장하는지 주변 코드를 읽어야 합니다.', '잠금을 잡은 구간에서 swake_up_locked(q, 0)를 딱 한 번 부릅니다. 0은 이 호출에 더할 깨움 표시가 없다는 값입니다. 내부 함수는 비어 있으면 끝내고, 아니면 첫 항목을 깨우려 시도한 뒤 그 항목을 줄에서 제거합니다.', '마지막 raw_spin_unlock_irqrestore는 잠금을 풀고 저장했던 인터럽트 상태를 복구합니다. 처음 켜져 있었다면 켜지고, 꺼져 있었다면 꺼진 채로 돌아옵니다. 언제나 켜는 unlock_irq와 이 restore 규칙을 구별하세요.', '깨움 요청과 작업 완료는 다릅니다. 부름을 받은 작업이 실행 기회를 얻고 조건을 다시 확인한 뒤 실제 일을 해야 합니다. 이 함수는 void라 완료 여부를 결과값으로 돌려주지도 않습니다. 공유 조건을 바꾸는 쪽과 확인하는 쪽이 필요한 보호 규칙을 함께 지켜야 합니다.'], [('swake_up_one을 부르기 전 해당 CPU의 인터럽트가 꺼져 있었어요. 끝나면 무조건 켜지나요?', ['네. 끝날 때에는 항상 켜요', '아니요. 저장한 이전 상태로 돌리므로 꺼진 상태를 유지해요'], 'irqsave가 이전 상태를 flags에 보관하고 irqrestore가 되돌립니다. 처음 꺼져 있었다면 끝나도 꺼져 있어요. 이름이 비슷한 irq 방식과 저장·복구 방식은 다릅니다.'), ('한 항목에 깨움 요청을 보냈어요. 그 작업이 할 일도 전부 끝난 건가요?', ['아니요. 작업이 실행되어 조건을 확인하고 일을 해야 해요', '네. 이 함수가 그 작업의 완료까지 기다려요'], '깨우기는 실행할 수 있도록 하는 과정입니다. 일을 끝냈다는 확인이 아니에요. 교실에서 이름을 불렀다고 그 친구가 맡은 준비를 이미 끝낸 것은 아닌 것과 같습니다.')]), 'os1498': ('지금 줄에 있는 A와 B의 카드를 임시 바구니로 옮겨 이번 호출 명단을 만든다고 해 봅시다. 그 뒤 원래 줄에 온 C의 카드는 이번 바구니에 저절로 들어가지 않습니다.', '임시 목록으로 옮긴 대상과 나중에 등록된 대기 항목을 구별합니다.', '원래 줄 A → B를 tmp로 옮기고 원래 줄은 비우세요. A 처리 뒤 새 C가 원래 줄에 들어왔다면 tmp와 원래 줄에 누가 남는지 적으세요.', ['swake_up_all은 먼저 LIST_HEAD(tmp)로 빈 임시 목록을 만듭니다. tmp는 이번 호출에서 처리할 항목들을 잇는 기준점입니다. 작업 본체를 새로 만드는 공간이 아니라 기존 항목들을 연결해 둘 목록입니다.', 'raw_spin_lock_irq로 인터럽트를 끄고 줄의 잠금을 잡은 뒤 list_splice_init을 실행합니다. 이 명령은 그 시점에 원래 줄에 있던 항목들을 tmp로 옮기고 원래 줄은 빈 상태로 만듭니다. 항목들을 통째로 복사해 두 벌 만드는 것은 아닙니다.', '반복문은 tmp의 첫 항목을 고릅니다. 그 작업을 TASK_NORMAL 대상으로 깨우려 하고, list_del_init으로 항목을 빼서 연결을 초기화합니다. 임시 목록에 항목이 남아 있으면 잠금과 인터럽트를 풀었다가 다시 잠급니다.', '왜 매번 길게 잡고 있지 않을까요? 많은 항목을 한꺼번에 처리하는 동안 다른 중요한 작업을 오래 막지 않기 위해서입니다. 중간에 잠금을 풀면 다른 작업이 실행할 기회를 얻을 수 있습니다. 그렇다고 다른 작업이 반드시 그 순간 실행되거나 전체 처리 시간이 일정하다는 뜻은 아닙니다.', '옮기기를 끝낸 뒤 원래 줄에 새로 등록된 C는 tmp에 자동으로 추가되지 않습니다. 예를 들어 tmp에 B가 남아 있고 원래 줄에 C가 생겼다면 이번 반복은 B를 처리합니다. 단, 함수를 부른 뒤라도 실제 옮기기 전에 등록된 항목은 옮기는 시점의 줄에 포함될 수 있습니다. 기준은 호출 시작 시각보다 list_splice_init 시점입니다.', '이 함수는 이미 인터럽트가 꺼진 상태에서 부르면 안 된다고 원문이 명시합니다. 중간에 켤 수 있어야 하기 때문입니다. 마지막 항목 뒤에는 반복문을 나와 한 번 잠금을 풀고 끝냅니다. 총 작업량은 대상 수에 따라 늘어나며, 한 번에 계속 잠금을 잡는 시간을 나누는 것과 전체 작업 수를 줄이는 것은 다릅니다.'], [('A와 B를 tmp로 옮긴 뒤 새 C가 원래 줄에 등록됐어요. C도 이번 tmp 반복에 자동으로 들어가나요?', ['네. 새 등록을 계속 가져와 모두 처리해요', '아니요. 옮긴 뒤의 새 등록은 원래 줄에 있어요'], 'list_splice_init은 실행한 그 시점의 목록을 옮깁니다. 반복문이 보는 것은 tmp이며 원래 줄을 매번 다시 가져오지 않아요. 함수 호출 뒤라도 옮기기 전에 등록한 경우와는 구별하세요.'), ('이미 인터럽트를 꺼 둔 상황에서 일반 swake_up_all을 호출해도 되나요?', ['아니요. 이 함수의 사용 조건에 맞지 않아요', '네. swake_up_one처럼 언제나 이전 상태를 저장해 복구해요'], '이 함수는 항목 사이에 인터럽트를 켤 수 있어야 합니다. irqsave·irqrestore를 쓰는 one과 다르므로 원래 꺼진 상태를 보존하는 함수라고 생각하면 안 됩니다.')]), 'os1499': ('특정 행사 담당자만 쓰는 별도 처리 절차가 있다고 해 봅시다. 이름이 일반 절차와 비슷해도 준비 조건이 다르면 아무 곳에나 바꾸어 쓸 수 없습니다.', 'completion 전용 전체 깨우기의 잠금 유지와 사용 범위를 이해합니다.', '일반 all 옆에는 항목 사이 잠금 풀기, all_locked 옆에는 잠금 유지라고 쓰세요. all_locked를 둘러싸는 호출자 잠금 잡기·풀기 상자를 그리세요.', ['swake_up_all_locked는 줄이 비어 있는지 확인하고, 비지 않았으면 swake_up_locked를 반복해서 부릅니다. 내부 한 번의 호출이 첫 항목을 제거하므로 A → B → C는 A, B, C 순서로 줄에서 빠집니다.', '이 함수 본문에는 잠금을 풀거나 다시 잡는 명령이 없습니다. 호출자가 이미 잡은 잠금을 계속 보유한 채 반복합니다. 이름의 locked는 그 사용 조건을 읽는 힌트입니다. 일반 swake_up_all처럼 중간에 잠금을 풀 것이라고 추측하면 안 됩니다.', '원문은 이 함수를 completions를 위해서만 제공하고 일반 용도로 쓰는 함수가 아니라고 설명합니다. completion은 다른 작업이 어떤 일을 마쳤다는 알림을 기다리는 커널 장치입니다. 모든 대기 줄을 가리키는 이름은 아닙니다.', '실제 complete_all을 보면 그 관계를 확인할 수 있습니다. 호출자가 x->wait.lock을 잡고 완료 표시 x->done을 UINT_MAX로 설정한 뒤 swake_up_all_locked를 부르고 잠금을 풉니다. UINT_MAX는 그 unsigned int 형식의 가장 큰 값입니다. 여기서는 여러 대기자가 완료를 확인할 수 있게 하는 표시로 쓰입니다.', '일반 all과 달리 인터럽트 처리 중이거나 인터럽트를 꺼 둔 구간에서 사용할 수 있도록 만든 별도 경로입니다. 그렇다고 모든 문맥에서 무조건 안전하다는 뜻은 아닙니다. 상위 completion 함수와 실시간 커널 설정 등이 요구하는 규칙을 함께 지켜야 합니다.', '잠금을 계속 보유하면 그 잠금을 필요로 하는 다른 실행 흐름은 중간에 줄을 바꿀 수 없습니다. 반면 처리할 항목이 많으면 그만큼 계속 잡고 있는 구간이 길어질 수 있습니다. 특별한 사용 목적의 함수를 “일반 all을 못 부르니 대신 쓰자”는 식으로 바꾸어 사용하면 안 됩니다.'], [('swake_up_all_locked도 항목 한 개를 처리할 때마다 잠금을 풀까요?', ['네. 일반 swake_up_all과 같은 반복이에요', '아니요. 잡고 있는 잠금을 유지한 채 반복해요'], '본문에는 비었는지 검사하는 while과 swake_up_locked 호출이 있고 unlock은 없습니다. 호출자가 잠금을 잡은 조건에서 줄이 빌 때까지 처리해요. 일반 all과 이름이 비슷해도 순서는 다릅니다.'), ('원문이 설명하는 all_locked의 제공 목적은 무엇인가요?', ['completion을 위한 특별한 인터페이스예요', '모든 일반 대기 줄에 권하는 기본 깨우기예요'], '주석은 completions를 위한 것이며 일반 사용용이 아니라고 말합니다. 특정 사용 조건을 갖춘 상위 코드와 연결해서 읽어야 해요. 어떤 곳에서 호출 가능한 예외가 있다고 모든 곳에 권장되는 것은 아닙니다.')]), 'os1500': ('대기 카드를 줄 끝에 붙이되 이미 붙어 있다면 또 붙이지 않는다고 생각해 봅시다. 같은 카드 하나를 여러 번 연결하면 줄의 앞뒤 관계가 망가질 수 있으므로 등록 여부를 먼저 확인합니다.', '대기 준비에서 작업 주소 설정, 중복 없는 등록, 상태 설정의 순서를 배웁니다.', 'A → B 줄에 초기화된 C를 준비하면 A → B → C를 그리세요. C를 다시 준비할 때에도 C가 하나만 남는지 확인하고 조건 재확인 단계를 덧붙이세요.', ['__prepare_to_swait는 대기 항목 wait의 task를 current로 정합니다. current는 지금 실행 중인 작업입니다. 이것은 어떤 작업의 대기 카드인지를 적는 단계이고, 줄에 연결하는 단계와는 별개입니다.', '다음에는 list_empty로 항목의 task_list 연결을 확인합니다. 처음 사용하는 항목은 앞뒤가 자신을 가리키도록 초기화되어 있어야 합니다. 이 상태면 아직 연결되지 않은 것으로 보고 list_add_tail로 줄 맨 끝에 넣습니다. tail은 꼬리, 곧 끝이라는 뜻입니다.', '이미 줄에 연결된 항목이면 추가하지 않습니다. 예를 들어 A → B → C에서 C를 다시 준비해도 C를 두 번 넣거나 다시 끝으로 옮기지 않습니다. 항목을 새로 초기화해서 등록 여부를 숨기는 것도 안 됩니다. 실제 연결 상태를 유지해야 이 검사가 제 역할을 합니다.', '밑줄 두 개가 붙은 내부 함수에는 잠금 명령이 없습니다. 줄을 안전하게 바꿀 수 있도록 호출자가 필요한 보호를 마련해야 합니다. 내부라는 이름만으로 알아서 안전해지는 것은 아닙니다.', '외부 prepare_to_swait_exclusive는 raw_spin_lock_irqsave로 잠금과 인터럽트 보호를 마련하고 내부 함수를 부릅니다. 이어 set_current_state로 기다릴 상태를 설정하고, 잠금을 풀며 이전 인터럽트 상태를 복구합니다. 등록과 상태 설정이 보호 구간 안에서 이 순서로 이루어집니다.', '준비가 끝났다고 그 함수에서 이미 잠든 것은 아닙니다. 호출한 쪽은 조건을 다시 확인하고, 아직 기다려야 할 때 schedule로 실행 기회를 넘깁니다. 기다림이 끝나면 finish로 상태와 등록을 정리합니다. 준비 → 조건 확인 → 필요할 때 대기 → 정리를 나누어 읽어야 깨움을 놓치지 않는 흐름을 이해할 수 있습니다.'], [('A → B 줄에 아직 연결되지 않은 C를 준비해 등록하면 어디에 넣나요?', ['첫 항목 A를 덮어써요', '맨 끝에 넣어 A → B → C가 돼요'], '내부 함수의 list_add_tail이 끝에 추가합니다. 기존 A와 B를 지우거나 덮어쓰지 않아요. 이미 연결된 C를 다시 준비하면 검사에서 추가를 건너뛰므로 중복 카드도 생기지 않습니다.'), ('__prepare_to_swait만 부르면 그 함수가 직접 줄 잠금까지 잡아 주나요?', ['아니요. 호출하는 쪽의 보호가 필요해요', '네. task를 설정할 때 잠금도 자동으로 생겨요'], '내부 본문은 작업 주소 설정과 조건부 목록 추가입니다. 외부 prepare_to_swait_exclusive가 잠금을 잡은 뒤 이 내부 함수를 불러요. 자료에 값을 넣는 명령 자체가 잠금을 대신하지 않습니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_370.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
